SELECT QUARTER(c.signup_date) AS signup_quarter, CASE WHEN c.credit_limit >= 13900 THEN 'high' WHEN c.credit_limit >= 7800 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, SORT_ARRAY(COLLECT_SET(s.browser)) AS browser_list, SUM(CASE WHEN s.device = 'tablet' THEN 1 ELSE 0 END) AS tablet_count FROM sessions s LEFT JOIN customers c ON s.customer_id = c.id WHERE s.customer_id = 35 GROUP BY QUARTER(c.signup_date), CASE WHEN c.credit_limit >= 13900 THEN 'high' WHEN c.credit_limit >= 7800 THEN 'mid' ELSE 'low' END ORDER BY signup_quarter;
